insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 1, 'In which of the three wetting regimes does this engine read the water cut box?', '["In the intermittent regime alone.", "In the water-wet regime and the intermittent regime, since both carry water on the wall.", "In every one of the three, because the water cut scales the wetting factor in all of them.", "In the oil-wet regime alone, where it sets how much of the wall the water still reaches."]'::jsonb, 0, 'In the water-wet regime the wetting factor is 1.000000 whatever the box says, and in the oil-wet regime it is 0.000000 whatever the box says. Only the intermittent regime takes the water cut through to the factor, and it is range checked there.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 2, 'Select oil wet and the wetting factor is 0.000000. What does the engine then do with the band label and the remaining life?', '["It issues both alongside the zero, since a zero is a perfectly good number to label and to divide into.", "It withholds both and says the zero was assumed rather than calculated.", "It refuses the whole screening outright.", "It issues the band label and withholds only the life."]'::jsonb, 1, 'The arithmetic ran, so this is a withholding rather than a refusal. The engine''s own words are that the rate is zero because that was assumed and not because it was calculated, and that an unbounded life off a dropdown is the strongest reassurance on the screen arriving from the weakest input.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 3, 'On an oil-wet case, what does the engine report for the effective corrosion inhibition?', '["Zero percent, which is the honest reading when there is no metal loss left to remove.", "One hundred percent, since with the rate at zero the programme has removed everything.", "An absence rather than a figure, reported as null.", "The water-wet percentage, unchanged."]'::jsonb, 2, 'A reported zero percent inhibition on a line that carries a corrosion inhibitor programme would be a statement about the programme, and it would be a false one. With the rate zero by assumption there is nothing for the corrosion inhibitor to be effective against, so the percentage has no subject.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 4, 'A user types a wetting regime the engine cannot resolve. What happens?', '["It falls through to the water-wet branch, which is the most limiting of the three regimes.", "It falls through to the intermittent branch.", "It resolves to whichever regime was used last.", "It refuses, and the message names the three regimes and quotes the string it was given."]'::jsonb, 3, 'The wetting regime can take the rate to zero on its own, so resolving an unrecognised string to any branch would be choosing that lever on the user''s behalf from a typing mistake. The engine works hard to understand what was meant and never invents what was meant.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 5, 'The strings oilWet, OILWET, oil-wet, Oil Wet and oil_wet all reach the same branch. What does that tell you about the matcher?', '["It accepts any string containing the letters of a regime name in any order at all.", "It is insensitive to case and to punctuation.", "It is insensitive to case only, and the punctuated spellings reach the branch by a separate alias list.", "It strips every character that is not a letter and then matches on the first three letters it is left holding."]'::jsonb, 1, 'Five spellings of one idea resolve because they are unambiguous. The generosity stops at ambiguity: a string the matcher cannot resolve refuses by name rather than falling through to a branch.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 6, 'In the water-wet regime the water cut box is set to 0.370000. What is the wetting factor?', '["0.370000, because the box is read in every one of the three regimes.", "The oil fraction, because that is what the factor is in this branch.", "1.000000, because the box is not read in this regime.", "The engine refuses the case."]'::jsonb, 2, 'A learner who moves the box in the wrong regime and sees nothing happen has found a real property of the model rather than a fault in the screen.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 7, 'Set the regime to intermittent and the water cut to 1.000000. Which regime''s answer do you land on?', '["The water-wet answer, at a wetting factor of 1.000000.", "The oil-wet answer, at a factor of 0.000000.", "Neither, since it is a third mechanism.", "The water-wet answer, once availability is raised."]'::jsonb, 0, 'The intermittent branch takes the water cut straight through to the wetting factor, so at a water cut of 1.000000 it produces the water-wet factor and at a water cut of 0.000000 it produces the oil-wet one.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 8, 'The water cut argument carries a default parameter of one in the engine signature. Which way does that default point?', '["Towards the least limiting answer, because the wetting factor it supplies is the smallest the regime can take.", "Neither way, because a default parameter is never reached from the studio layer or from a direct caller.", "Towards the least limiting answer, because it silently switches the branch to oil wet.", "Towards the most limiting answer, because a wetting factor of 1.000000 is the largest value the regime can take."]'::jsonb, 3, 'A direct caller that omits the key entirely gets a wetting factor of 1.000000, which is the water-wet answer, and the digest records that direction as conservative. A water cut typed as not-a-number refuses instead, and not-a-number is what the studio layer produces from a blank box.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 9, 'Inside the intermittent regime a water cut arrives as not-a-number. What does the engine return?', '["A wetting factor of 1.000000, taken from the default parameter that argument carries in the engine signature.", "A wetting factor of 0.000000, the safest value available.", "A refusal naming the input: the intermittent regime needs a finite water cut fraction.", "A screening with that row left empty."]'::jsonb, 2, 'A default parameter is reached only when an argument is genuinely absent. A value that is present and is not a number is a different thing. That is why the live studio never reaches the default, because a blank box produces not-a-number.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 10, 'A water cut of 5 is typed into the intermittent regime. Why does the engine refuse it?', '["A fraction is checked against nought to one, and five is outside it.", "A water cut above one is read as a percentage, and the engine will not guess which unit was meant.", "The engine refuses any water cut larger than its own default parameter would supply.", "It exceeds the corrosion inhibitor availability."]'::jsonb, 0, 'Nought to one on every fraction is one of the range guards this module enforces on what a caller types. The message names the value it was given, and a water cut of -0.1 refuses with the same shape.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 11, 'Why does the engine describe the oil-wet zero as assumed rather than calculated?', '["The correlation returned a small positive value that the wetting factor then rounded down to exactly zero.", "The zero follows by arithmetic from a word chosen in a list, and nothing was measured to produce it.", "The result sits below the smallest positive value this module is able to print, so it is reported as zero.", "The corrosion inhibitor programme on that case removed the whole of the metal loss for the whole of the year."]'::jsonb, 1, 'The multiplier for the oil-wet regime is 0.000000, that multiplier reaches the rate, and the regime arrived from a dropdown. The strongest reassurance on the screen would otherwise arrive from the weakest input.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 12, 'Across the three wetting regimes, with every other input held still, what happens to the rate?', '["It moves by less than the corrosion inhibitor availability moves it across that input''s own range.", "It stays where it is, because the wetting factor is applied after the band label has been chosen.", "It moves only between the water-wet and the intermittent branches, the oil-wet branch being a refusal.", "It runs from its full water-wet value down to zero, with nothing but the dropdown moved."]'::jsonb, 3, 'One dropdown takes the rate to zero with nothing else touched, and that is why the regime carries a module of its own at this tier.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 13, 'What separates the oil-wet withholding from a refusal?', '["There is nothing at all between them, since both of them leave the field entirely blank on the screen that the user is actually reading.", "A withholding names the input at fault and a refusal does not.", "A refusal means no answer is available, while a withholding means the arithmetic ran and its outputs would mislead as verdicts.", "A refusal clears when you retype the input."]'::jsonb, 2, 'On the oil-wet case the rate is reported. The band label and the remaining life are held back, and that is the smallest withholding that keeps the summary consistent with the arithmetic.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 14, 'The regime list is closed at three entries. What follows for a reader arriving from multiphase flow?', '["A fourth entry is reachable by typing a flow pattern name, which the matcher resolves to the nearest of the three.", "There is no flow-pattern model here, so the regime is a coarse interpretation the engineer supplies.", "The three entries are derived from the line hydraulics this module computes alongside the corrosion rate.", "The list is short because a longer one would not fit the dropdown."]'::jsonb, 1, 'A gasWet string refuses, and so does an empty string, which is what a form produces before anybody has chosen. The module will not tell you which regime a line is in and it holds nothing to work it out from.'),
  ('corrosion', 'intermediate', 'module', 'm01-the-wetting-regime', 15, 'On an oil-wet case, which parts of the screening still compute?', '["The wall shear and the chemistry figures, because none of them depends on the regime.", "Nothing at all, since the regime sits at the top of the calculation.", "The band label and the remaining life alone.", "Only the corrosion inhibitor arithmetic."]'::jsonb, 0, 'Only the fields downstream of the rate are held back. Reading what survives is how you tell a withholding from a refusal on the screen itself.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 1, 'A corrosion inhibitor runs at 95.000000 percent efficiency and 80.000000 percent availability. What is the effective protection?', '["95.000000 percent, because the efficiency is the property of the chemical.", "76.000000 percent.", "80.000000 percent, because availability is the limit and it caps the answer.", "The average of the efficiency and the availability, as a percentage."]'::jsonb, 1, 'The uninhibited rate applies for the fraction of the time the chemical is off the wall, so the two percentages combine rather than one of them winning. The engine takes them as separate inputs for exactly this reason.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 2, 'At 95.000000 percent efficiency and 80.000000 percent availability, by how many percentage points does the effective protection fall short of the datasheet figure?', '["0.100000 percentage points, which is where the engine''s warning first fires at any efficiency.", "4.800000 percentage points.", "19.000000 percentage points.", "15.250000 points."]'::jsonb, 2, 'The datasheet figure is the efficiency, so the shortfall is the efficiency less the effective protection. The metal loss ratio on that same row is a separate field and it is 4.800000 times the datasheet number.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 3, 'One row shows an effective protection of 76.000000 percent. By what factor does its metal loss exceed the datasheet number?', '["4.800000 times it.", "1.950000 times it, which is what the 95 percent availability row carries.", "1.380000 times it, which is what the engine reports two percentage points higher up.", "19.000000 times it, the same figure the shortfall column carries on that row."]'::jsonb, 0, 'What survives the corrosion inhibitor is the small remainder, and it is the remainder that sets the loss. That is why the loss column grows faster than the protection column falls.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 4, 'Which input limits the result on the 80.000000 percent availability row, in the engine''s own words?', '["Efficiency limits it, because the datasheet figure sets the ceiling on protection.", "The two limit it equally, since the protection is their product.", "Neither limits it, because the corrosion inhibitor credit is removed at that shortfall.", "Availability limits it and efficiency does not, once the chemical is good."]'::jsonb, 3, 'The engine''s own warning on that case reads that a 95 percent inhibitor at 80 percent availability gives 76.0 percent effective protection, which is 4.80 times the metal loss of the datasheet number, and it names availability as what limits it. Those are the engine''s words and they are quoted verbatim in the digest.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 5, 'Against what does the metal loss ratio compare?', '["Against an uninhibited line carrying no corrosion inhibitor programme at all.", "Against the corrosion allowance the reader typed into the screen.", "Against the datasheet row, which is the same chemical at one hundred percent availability.", "Against the rate the same line would show one band label lower."]'::jsonb, 2, 'A ratio of 1.000000 means the programme delivered what the container promised. It says nothing about how fast the wall is going away, because a line can sit at 1.000000 and still lose metal quickly.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 6, 'At 95.000000 percent efficiency, which availability row carries a metal loss of 15.250000 times the datasheet number?', '["50.000000 percent, where the shortfall equals the protection.", "25.000000 percent.", "70.000000 percent, which is the lowest row the engine will accept.", "90.000000 percent, which is the shipped availability on the studio case."]'::jsonb, 1, 'At 50.000000 percent availability the effective protection is 47.500000 percent and the loss is 10.500000 times the datasheet number. Keep going down the column and the loss keeps rising in equal steps per percentage point, reaching 15.250000 times at 25.000000 percent.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 7, 'On which availability row is the datasheet figure the number the wall actually sees?', '["At 95.000000 percent, which is the availability the studio ships with.", "At 98.000000 percent, where the shortfall rounds to nothing worth reporting.", "On every row, since the datasheet figure is the efficiency and the efficiency never moved.", "At 100.000000 percent, where the shortfall is 0.000000 percentage points."]'::jsonb, 3, 'That row also requires the chemical to be present every hour of the year, with no shutdown and no empty tank, so treating the datasheet figure as the protection treats an unreachable case as the base case.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 8, 'The studio ships with a corrosion inhibitor at 90 percent efficiency and 95 percent availability. What does it deliver?', '["85.500000 percent effective protection, a shortfall of 4.500000 percentage points.", "90.000000 percent effective protection, with no shortfall reported anywhere on the screen.", "95.000000 percent effective protection, taken from the availability figure.", "76.000000 percent effective protection, with a shortfall of 19.000000 points."]'::jsonb, 0, 'A reader who takes 90 percent off the datasheet and stops has overstated the protection by those 4.500000 percentage points on the first case the app ever shows them, and the warning is present on that screen.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 9, 'Type an efficiency of 100 percent with an availability of 95.000000 percent. What comes back?', '["A refusal, because no corrosion inhibitor removes all of the metal loss.", "An effective protection of 100.000000 percent, the efficiency being taken as typed.", "An effective protection of 95.000000 percent, with no clamp and no hidden ceiling.", "An effective protection clamped by a hidden ceiling belonging to the engine itself."]'::jsonb, 2, 'When the chemical removes everything while it is on, the time average has to give exactly the availability. The engine computes it and annotates it rather than refusing it.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 10, 'What does the engine add beside an effective protection computed from a typed 100 percent efficiency?', '["A clamp message recording that the efficiency was moved down from the figure typed in.", "A note saying the figure is the arithmetic of the number typed in and is not a prediction.", "A refusal to issue a remaining life from a rate reached that way.", "Nothing, because the arithmetic is correct and needs no annotation."]'::jsonb, 1, 'The engine''s own note goes on to say that no inhibitor removes all metal loss while it is on. It draws the line between a calculation, which is correct here, and a claim about a chemical, which it is not.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 11, 'A corrosion inhibitor efficiency of -5.000000 percent with an availability of 90.000000 percent. What does the engine do?', '["It clamps the efficiency to zero, returns 0.000000 percent protection and names the clamp.", "It returns a negative effective protection, since the chemical is then being modelled as an accelerant.", "It refuses, because a negative percentage cannot be a corrosion inhibitor efficiency.", "It clamps the availability instead and returns 90.000000 percent protection."]'::jsonb, 0, 'Nothing in this module models an accelerant, so inventing that behaviour from a typing mistake would be a claim with nothing behind it. Zero is the nearest value the model can stand behind and the move is declared.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 12, 'An efficiency of 120.000000 at 90.000000 percent availability, and an efficiency of 90.000000 at 130.000000 percent availability, both return 90.000000 percent effective protection. How does a reader tell the two cases apart?', '["By the shortfall, which differs between the two because a different input was clamped.", "By the metal loss ratio, which the engine reports only on the second of the two.", "They cannot be told apart, because the engine reports no clamps for either case.", "By the clamp message, which names the input that was moved and the value it was moved from."]'::jsonb, 3, 'Two different mistakes reach one identical protection figure. Without the declaration they would produce one identical screen, which is why the clamps come back on the screening in a field of their own rather than in a paragraph.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 13, 'The corrosion inhibitor warning fires on the effective shortfall. What is the trigger?', '["An efficiency strictly above 90.000000 percent, whatever the availability.", "0.100000 percentage points of shortfall, at any efficiency at all.", "A shortfall of 4.500000 percentage points, which is the shipped case.", "A metal loss ratio above 1.380000 times the datasheet number."]'::jsonb, 1, 'The trigger was measured by bisecting the availability at which the warning first appears. It is low enough that essentially any real programme carries the warning, which is the intended behaviour, because the shortfall is the point of the module.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 14, 'Why can a capstone in this course grade the corrosion inhibitor arithmetic while it grades no corrosion rate the correlation produced?', '["The corrosion inhibitor constants are published in the open literature and the correlation constants are not sourced.", "The arithmetic is validated against the golden and the correlation is not.", "The arithmetic is two typed percentages and a division, with no correlation constant anywhere in the chain.", "The arithmetic is exported by the engine and the correlation is held inside it."]'::jsonb, 2, 'No fugacity coefficient, no held threshold and no band edge reaches the effective protection, the shortfall or the metal loss ratio. You can check every one of them on paper, and so can a grader.'),
  ('corrosion', 'intermediate', 'module', 'm02-efficiency-is-not-protection', 15, 'Efficiency and availability are asked for separately. What kind of quantity is each?', '["Efficiency is a laboratory property of a chemical and availability is a property of an operation.", "Both are properties of the chemical, measured on the same laboratory loop.", "Both are operating records, taken from the injection skid over the year.", "Efficiency is measured on the line and availability is quoted on the datasheet."]'::jsonb, 0, 'Efficiency is chosen once, at the point of selection, and rarely moves. Availability is pump uptime, tank level, injection point and delivery schedule, and it moves every week. One box would average a laboratory result and an operating record into a number belonging to neither.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 1, 'This module computes a wall shear stress. What question is that number there to answer?', '["Whether the velocity has passed an erosional limit for the line.", "Whether the flow has reached the point where mechanical erosion begins.", "Whether a corrosion inhibitor film survives on the steel.", "Whether the pressure drop is within the line''s allowance."]'::jsonb, 2, 'This engine has no erosional-velocity criterion at all and carries no model of mechanical erosion or erosional wall loss from entrained solids or liquid impingement. The Casing and Tubing Design course at its Expert tier is where that criterion is owned on this platform.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 2, 'Which course on this platform owns the erosional velocity criterion?', '["The Casing and Tubing Design course, at its Expert tier.", "This one, in the module that computes the wall shear.", "The Pipeline and Line Sizing course, at its Associate tier.", "The Well Integrity and P and A course, in the Drilling module."]'::jsonb, 0, 'This course cites the owner and states that this engine has no erosional-velocity limit, which is a pivot between two courses rather than a derivation you can run here. The repair deliberately did not add one.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 3, 'One of the digest''s streams runs at a Reynolds number of 3.3754. Which branch does this module''s friction factor take there?', '["The turbulent branch, since every production stream is turbulent.", "Neither, because the engine refuses a Reynolds number below the switch.", "Both, because the engine blends the two branches near the switch.", "The laminar branch."]'::jsonb, 3, 'That stream is viscous, small and slow, and it is in the digest so a lesson has one laminar case. Its friction factor comes from the other expression entirely.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 4, 'At what Reynolds number does this module''s friction factor change branch, and how was that figure established?', '["At 2000.0000, read from the engine''s own exported constant.", "At 4000.000000, bisected on the branch NAME the engine returns.", "At 4000.000000, taken from the published transition for pipe flow.", "It has no single switch value, the branch being chosen from the velocity."]'::jsonb, 1, 'Measuring rather than reading an export is deliberate throughout this course. An export tells you what the module declares and a measurement tells you what it actually uses. The switch value is held for literature either way.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 5, 'By what factor does the wall shear jump across this module''s friction branch switch?', '["2.189815, across two ten-thousandths of the Reynolds number.", "1.000000, because the two branches are constructed to meet at the switch.", "4.699248, which is the factor the stripped stream''s rate ratio carries.", "2.189815, but only once the velocity has doubled across the switch."]'::jsonb, 0, 'Two ten-thousandths of the Reynolds number is a fraction of a percent of velocity. Nothing in either expression requires the two to agree at any particular value, so joining them at one produces a step wherever they stand there.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 6, 'Why does the engine leave that step unsmoothed?', '["Because the step is too small to be visible at the precision the studio prints.", "Because smoothing it would break the Reynolds number the line sizing course computes.", "Because a smoothing function would be a third correlation with no source behind it.", "Because the two branches already agree everywhere except at one single value."]'::jsonb, 2, 'Blending the branches invents a curve. Picking one branch either side and saying nothing is what a reader would assume is happening. The engine computes the branch, flags the neighbourhood and says what the step means.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 7, 'What does the engine do when the Reynolds number sits inside ten percent of the switch?', '["It refuses the shear, because the value there is not a single number.", "It sets a nearSwitch flag and returns a note telling the reader to read the shear as a bracket.", "It returns the average of the two branches and marks the row as blended.", "It returns the laminar value and records that the turbulent one was rejected."]'::jsonb, 1, 'The engine''s own words on that note are that the friction factor is discontinuous there and the shear jumps by about a factor of two, and that the number should be read as a bracket. Near the switch the shear has two candidates in it, and away from it the shear is a single number.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 8, 'Two numbers turn the wall shear into a word. What is their status in this repository?', '["Both are published values that the engine cites in its own docstring alongside the correlation.", "One is published and the other was measured on the Tunu stream.", "Both were fitted to the vendored golden, which carries the sourcing.", "Both are held for literature, so no source for either value exists anywhere in it."]'::jsonb, 3, 'Measured out of the engine by bisecting the velocity at which the risk word changes, they are 100.000000 Pa and 50.000000 Pa. The engine declares both in its own held list and the studio prints that list behind a disclosure.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 9, 'What does the film-stripping threshold drive in this engine as it ships?', '["A coloured word, a warning paragraph and the corrosion inhibitor credit itself.", "A coloured word and nothing else, the rate being computed independently of it.", "An inspection interval, which the screening returns alongside the remaining life.", "The erosional velocity limit the module compares the typed velocity against."]'::jsonb, 0, 'The third of those is the one that changes the arithmetic. An unsourced number that colours a label is a presentation choice, and an unsourced number that removes a credit from a rate is part of the calculation.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 10, 'For the Tunu stream, the velocity at which the film-stripped flag turns true was found by bisection. What is it?', '["8.126015 m/s, and the wall shear there is 50.000000 Pa.", "12.000000 m/s, which is the lowest swept velocity carrying a high risk word.", "8.126015 m/s, and the wall shear there is 100.000000 Pa.", "It has no single value, the flag turning on a range of velocities."]'::jsonb, 2, 'So the threshold is a single value, reachable at a single velocity on a stated stream, and the engine will give that velocity to six decimals. The precision is honest about the arithmetic and says nothing about where a real corrosion inhibitor film actually fails.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 11, 'This module''s friction factor and this module''s Reynolds number are not the platform''s only ones. What should a reader do about that?', '["Prefer this module''s pair, because the corrosion screening is the later calculation.", "Use each module''s own number inside that module, since the two correlations will not agree on one pipe.", "Prefer the line sizing pair, because line hydraulics is where the pipe is sized.", "Average the two, because neither correlation is sourced in this repository."]'::jsonb, 1, 'The Pipeline and Line Sizing course computes both with a different correlation and a different laminar to turbulent transition, and the engine says so in its own docstring. This course names the seam rather than hiding it, because removing the duplicate is a cross-module decision.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 12, 'The density box is left blank on a whole screening. What comes back?', '["A shear row left empty, with every other row computed as usual.", "A shear computed from a default density the engine supplies.", "A shear of zero, which the film-risk word is then taken against.", "A refusal saying the film survival check did not run, and naming the density."]'::jsonb, 3, 'The engine''s own message says wall shear stress needs a positive density. The screening computes the shear first because the rate depends on the film verdict, so a shear that cannot be computed stops the whole screening.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 13, 'A viscosity of zero is typed into the shear door. What does the engine return?', '["A Reynolds number of infinity, with the turbulent branch selected for the friction factor.", "A wall shear of zero, since the friction factor vanishes with the viscosity.", "The same refusal a blank viscosity gets, because both fail the positive test.", "A screening marked complete, with the viscosity row flagged as assumed."]'::jsonb, 2, 'The message is that wall shear stress needs a positive viscosity. Four inputs reach this door and each of the four refusals names its own box, which is the pattern throughout this module.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 14, 'Inside this module, which of the two quantities is a definition rather than a correlation?', '["This module''s Reynolds number, formed from a density, a velocity, a diameter and a viscosity.", "This module''s friction factor, read off one of the two branches.", "The wall shear, formed from the friction factor and the flow.", "Neither, because both rest on constants held for literature."]'::jsonb, 0, 'That split is why this course can grade a Reynolds number and grades no friction factor and no wall shear. The held Blasius pair and the branch switch act downstream of the Reynolds number.'),
  ('corrosion', 'intermediate', 'module', 'm03-wall-shear', 15, 'On the studio''s shipped default case, what is this module''s Reynolds number?', '["313781.4400, which is the figure the first of the digest''s streams carries.", "416686.8569.", "1063231.0691, the figure carried by the one stream whose film is stripped.", "63287.5636, which is the swept row at one metre a second."]'::jsonb, 1, 'Reynolds numbers print to four decimals in this course, because a number in the hundreds of thousands carries no information in its millionths. That case is turbulent and its wall shear is 14.408065 Pa.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 1, 'The wall shear says the corrosion inhibitor film is gone. What does this engine do with the rate?', '["It computes the rate with the credit taken in full and prints a warning under it.", "It refuses the rate, because the corrosion inhibitor programme no longer describes the line.", "It computes both rates and reports whichever of the two is the larger as the answer.", "It computes the rate with the credit removed and reports the credited rate beside it."]'::jsonb, 3, 'A rate that still carried the credit with a warning underneath would leave the number and the sentence beside it disagreeing, and a reader resolves that by trusting the number. Here the arithmetic carries the verdict.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 2, 'What new correlation was written to remove the corrosion inhibitor credit?', '["A stripped-film correlation fitted to the two shear thresholds.", "None. The credit is simply not taken, so the rate is the uninhibited rate for those conditions.", "A derating curve on the datasheet efficiency, indexed by the wall shear.", "A second mass-transfer term that applies once the film has gone."]'::jsonb, 1, 'That is why the relationship between the two rates stays arithmetic rather than becoming a second model. Both rates run through the same chain with the same inputs and differ in one factor.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 3, 'For the one digest stream whose film is stripped, the stripped rate is how many times the credited rate?', '["1.000000 times, as it is on every other stream in that table.", "6.896552 times, which is the figure the shipped case reaches at 60 ft per second.", "4.699248 times.", "2.189815 times, which is the jump across the friction branch switch."]'::jsonb, 2, 'That factor is exactly the reciprocal of the fraction of the metal loss the corrosion inhibitor programme leaves behind. The digest asserts the property to twelve figures on every rebuild.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 4, 'What quantity does the ratio of the stripped rate to the credited rate equal?', '["The reciprocal of the fraction of the metal loss the corrosion inhibitor programme leaves.", "The ratio of the wall shear on the case to the film-stripping threshold it was taken against.", "The ratio of the two band edges the rate happens to sit between.", "The ratio of the uninhibited rate to the mass-transfer term."]'::jsonb, 0, 'Nothing in the correlation is in it. The two rates share the whole chain and every held constant, coefficient and correction factor divides out exactly.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 5, 'Why can a graded capstone field in this course be a ratio of two lives?', '["Because the remaining-life door is the only one the engine exports by name.", "Because the allowance is common to both, so the ratio reduces to the corrosion inhibitor arithmetic.", "Because the band edges cancel between the two lives on the same case.", "Because a life in years is a measurement rather than a derived figure."]'::jsonb, 1, 'The remaining life is a remaining allowance divided by a rate, and the allowance is the same on both sides, so the ratio of the two lives is the ratio of the two rates the other way up. Neither carries a held constant.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 6, 'Take the shipped studio case and raise the velocity from 10 to 60 ft per second. What is the ratio between the rate and the credited rate there?', '["4.699248, the same figure the stripped digest stream carries.", "1.45, which the shipped warning names on the default case.", "1.000000, because the chemistry was not altered between the two screens.", "6.896552."]'::jsonb, 3, 'The two stripped cases in this course have different temperatures, different pressures, different chemistry and different lines. Their ratios differ because the two corrosion inhibitor programmes differ, and for no other reason.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 7, 'At 60 ft per second on the shipped case, what happens to the remaining life?', '["It falls from 4.207953 yr to 0.242737 yr.", "It falls from 4.207953 yr to 0.760876 yr, which is the stripped digest stream''s credited life.", "It is withheld, because the corrosion inhibitor credit is no longer being taken on that case.", "It is unchanged, because the allowance and the design life were not altered."]'::jsonb, 0, 'Nothing about the chemistry moved between those two screens. One flow input moved and the module changed which rate it was willing to stand behind, and the life follows the rate.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 8, 'Take the shipped case to 60 ft per second. Which wall shear produced the stripped verdict there, and what was it measured against?', '["14.408065 Pa, against that same stripping threshold measured at 100.000000 Pa.", "369.638295 Pa, against the moderate band this module measures at 50.000000 Pa.", "362.474888 Pa, against the measured stripping threshold of 100.000000 Pa.", "362.474888 Pa, against an erosional velocity limit this module carries."]'::jsonb, 2, 'The film risk is high there, the credit is removed and the rate the screen reports becomes the uninhibited one. The threshold itself is held for literature and no source for it exists in this repository.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 9, 'On a stream whose film survives, what do the rate column and the credited rate column show?', '["Two different figures, the credited one smaller.", "The same figure, and the ratio between them is 1.000000.", "One figure and one blank, the credited column being filled only when it differs.", "Two figures whose ratio is the availability."]'::jsonb, 1, 'Five of the digest''s six streams are in that position and on each of them the two rate columns agree and the two life columns agree. Printing a figure twice looks redundant until you meet the case where they differ.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 10, 'Why does the engine report the credited rate even when the credit was taken in full?', '["Because it is the rate a reader working from a datasheet efficiency already has in their head.", "Because the two figures are needed to form the band label on that case.", "Because the remaining life is computed from the credited rate rather than the rate.", "Because the capstone grades the credited rate rather than the rate itself."]'::jsonb, 0, 'A screen showing only the stripped rate would look like a different calculation rather than the same calculation with one credit removed. Printing both lets the reader see exactly what the shear verdict cost.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 11, 'The stripping threshold is held for literature. What does that leave a reader holding on a stripped case?', '["A single rate, since the engine has already chosen which of the two applies.", "A refusal, since no verdict can rest on a number with no source.", "A band label, which is the one field the threshold does not reach.", "A pair of bounds, the stripped rate if the held threshold is right and the credited rate if the film survives."]'::jsonb, 3, 'Nothing in this repository settles which of the two is true, so a reader who quotes both and says which assumption produces which is giving an honest account of what the module knows.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 12, 'In what order does the whole screening compute the shear and the rate?', '["The rate first, with the wall shear read afterwards only to colour the risk word.", "Both at once, the two of them being independent of one another on any case.", "The shear first, because the rate depends on whether the film survived it.", "The rate first, and the shear only when the rate has passed a band edge."]'::jsonb, 2, 'That ordering is forced by the coupling. Every step after the first is allowed to depend on the shear verdict, and reading the order tells you which parts of the screen are hostage to which inputs.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 13, 'The density box is blank, so the film survival check cannot run. Why does the engine refuse to issue a rate?', '["Because it does not know whether the corrosion inhibitor credit applies, so the rate would be one of two figures.", "Because the density is one of the arguments of the correlation from which this module''s corrosion rate is computed.", "Because a remaining life cannot be formed without a density for the stream.", "Because the band label is taken against a density corrected rate."]'::jsonb, 0, 'On the shipped case at 60 ft per second the two candidate rates differ by the ratio of 6.896552. Issuing one of them while the credit question is open would be choosing between them at random.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 14, 'Which four blank boxes produce the screening incomplete message?', '["The temperature, the pressure, the CO2 fraction and the in-situ pH.", "The density, the viscosity, the velocity and the line inside diameter.", "The corrosion allowance, the consumed depth, the design life and the rate.", "The wetting regime, the water cut, the efficiency and the availability."]'::jsonb, 1, 'Each of those four reaches the wall shear door, and each message has two halves: the first says the film survival check did not run, and the second names the box. A reader gets the cause and the fix from one sentence.'),
  ('corrosion', 'intermediate', 'module', 'm04-the-shear-acts-on-the-rate', 15, 'On the stripped digest stream the binding constraint names the wall shear. What does the engine say to change first?', '["Raising the corrosion inhibitor efficiency quoted on the chemical''s datasheet.", "Increasing the corrosion allowance that the line was originally built with.", "Slowing the line, which changes this answer before anything else does.", "Lowering the in-situ pH so the correction factor falls."]'::jsonb, 2, 'Its words are that the wall shear is above the value at which this module takes the film to be stripped, so the credit is removed and the rate is 4.70 times what the datasheet efficiency would give. The rate, the warning and the summary all say the same thing on that case.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 1, 'What arithmetic is the remaining life in this module?', '["The corrosion allowance less what has already gone, divided by a rate.", "The corrosion allowance divided by the design life that was typed in.", "The wall thickness less a minimum thickness, divided by a rate.", "The corrosion allowance multiplied by the effective corrosion inhibition."]'::jsonb, 0, 'Take the allowance, subtract the consumed depth, divide by a rate, and stop. That division is the whole of what the word integrity means in this course.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 2, 'On the studio''s shipped default case, what are the corrosion allowance and the consumed depth?', '["An allowance of 15.090473 mm and a consumed depth of 3.175000 mm.", "An allowance of 11.915473 mm and a consumed depth of 0.000000 mm.", "An allowance of 3.175000 mm and a consumed depth of 0.000000 mm.", "An allowance of 0.000000 mm and a consumed depth of 3.175000 mm."]'::jsonb, 2, 'With nothing consumed, the corrosion allowance and the remaining allowance are the same figure, which is why a reader can go a long way on that case without noticing that they are two separate quantities.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 3, 'What remaining life does the shipped case report?', '["0.242737 yr, which the same case reaches at 60 ft per second.", "4.207953 yr.", "20.000000 yr, which is the design life the case was given.", "36.112878 yr, which one of the digest''s own streams carries."]'::jsonb, 1, 'That is the remaining allowance divided by the rate, and nothing else. A remaining life of that size does not say when to inspect and it does not say what thickness to retire at.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 4, 'The shipped case carries a design life of 20.000000 yr. What verdict does the screening return against it?', '["That it is met, the allowance outlasting the stated design life.", "It is withheld.", "None is offered.", "That it is not met."]'::jsonb, 3, 'The binding constraint on that case is the corrosion allowance against the design life, and the engine reports the life it actually reaches beside the life it was asked for.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 5, 'On the shipped case, what allowance would a new line at the shipped rate have needed in order to reach the end of the stated design life?', '["15.090473 mm.", "3.175000 mm, which is the allowance the line already carries.", "11.915473 mm, which is the gap between two of the fields on that screen.", "0.000000 mm."]'::jsonb, 0, 'That field asks what a line at this rate would have needed to be built with in order to reach the end of the stated design life. It is a different question from how long this line has.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 6, 'What shortfall in millimetres does the shipped screen carry?', '["15.090473 mm, which is the allowance the design life demands.", "11.915473 mm.", "3.175000 mm.", "4.207953 mm."]'::jsonb, 1, 'The shortfall sits between the two allowance fields. It is the gap a reader has to close, measured from where the wall is now.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 7, 'On the shipped case the engine''s own binding constraint sentence names three figures. Which three?', '["The wall shear, the stripping threshold, and the metal loss ratio.", "The efficiency, the availability, and the effective protection.", "The rate, the years the allowance reaches, and the millimetres of allowance it is short by.", "The H2S ratio, the regime word, and the decades above the threshold."]'::jsonb, 2, 'Its words are that at 0.755 mm/yr the allowance runs out in 4.2 years against a 20 year design life, short by 11.92 mm of allowance. Of everything on that screen, this is the limit that governs the answer.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 8, 'Three studios in this suite take a corrosion allowance. What does each of them do with it?', '["This one consumes an allowance, while the line sizing and storage tank studios each add one.", "All three consume an allowance, and each returns a remaining life from it.", "All three add an allowance, this one adding it to the wall it screens.", "This one adds an allowance, and the other two consume one to give a life."]'::jsonb, 0, 'The line sizing studio adds one to a pressure-containing wall and the storage tank studio adds one to a shell course. The wall this studio is eating is not the wall either of those sized, and there is no link between the three.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 9, 'This module cannot say what the allowance is being taken off. Which calculation would answer that, and who owns it?', '["The erosional velocity criterion for the line, which the Casing and Tubing Design course owns at its Expert tier.", "The Kremser relation, owned by the Gas Processing course at its Professional tier.", "The remaining life division, which this module owns and already computes.", "The Barlow thin-wall relation with a design factor, owned by the Pipeline Network course at its Associate tier."]'::jsonb, 3, 'This module has no minimum thickness, so it cannot tell you how much wall sits underneath the allowance once the allowance is gone. Naming the owner and stopping is what this course does with a quantity another course already owns.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 10, 'Which course owns wall loss taken to a derated burst pressure?', '["The Pipeline Network course, at its Associate tier.", "The Torque and Drag Expert tier owns it.", "The Fluid Properties course, at its Expert tier.", "This one, which reports it beside the remaining life."]'::jsonb, 1, 'This module consumes an allowance and never computes a pressure, so the comparison between the two is a pivot from one course to another rather than a derivation you can run here.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 11, 'Which live Academy course refuses corrosion in its own scope statement, the refusal this course fills?', '["The Casing and Tubing Design course, which defers its erosional criterion to this one.", "The Storage Tank course, which takes its shell allowance from this module''s output.", "The Well Integrity and P and A course, which refuses corrosion, wall loss and remaining life in its own scope.", "The Fluid Properties course, which hands this one a fugacity for the rate."]'::jsonb, 2, 'FC9 fills exactly that refusal. The vocabulary does not travel in the other direction, because a barrier envelope is not a corrosion allowance and neither word can be substituted for the other.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 12, 'What does the word integrity mean in this course?', '["One arithmetic: a corrosion allowance divided by a rate.", "A fitness-for-service assessment against a recognised method.", "A minimum thickness compared against the measured wall.", "A barrier envelope holding pressure across a defined boundary."]'::jsonb, 0, 'The gap between that narrow reading and the usual one is where a screen gets over-read, which is why saying so wherever the word appears is a rule in this wave rather than a stylistic preference.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 13, 'An inspection interval, a minimum thickness, a retirement thickness and a fitness-for-service assessment are all absent here. In what sense?', '["They are held for literature, pending a source that would settle them.", "They are not provided, which is a decision rather than a number pending a source.", "They are computed and then withheld, because their inputs are assumed.", "They are present but disclosed only behind the studio''s held list."]'::jsonb, 1, 'Held means a source might settle it. Not provided means the module has taken a decision, and producing any of those four would mean adopting a standard this module does not carry. The engine exports both lists and the screening returns them.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 14, 'The one rate this engine returns is described as a general uniform rate. What does that rule out?', '["Reading it in mils a year alongside the millimetres a year the engine already returns.", "Reading it as the rate that the corrosion inhibitor datasheet efficiency would have given.", "Reading it as a wall-loss prediction for a weld, a bend, a top-of-line film or a pit.", "Reading it against a design life stated in years."]'::jsonb, 2, 'The module carries no localised model, so it cannot warn a reader who reads it that way. There is no pitting criterion and no localised rate anywhere in it.'),
  ('corrosion', 'intermediate', 'module', 'm05-the-allowance', 15, 'Set the shipped case to oil wet, so the wetting factor becomes 0.000000. What happens to the remaining life?', '["It is returned as unbounded, which the screening reports as a pass.", "It is unchanged at 4.207953 yr, the allowance not having moved.", "The whole screening refuses, naming the wetting regime as the input at fault.", "It is withheld."]'::jsonb, 3, 'An unbounded life is a number in the sense that a program can print it, and as a screening result it carries nothing, because it is true of every case where the rate is zero whatever put it there. A withheld field cannot be copied into a summary as a result.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 1, 'Why does the H2S to CO2 ratio need no pressure at all?', '["Because the engine applies a fugacity correction to both of the gases before it divides them.", "Both arguments are partial pressures, so the total pressure divides out of the ratio.", "Because the ratio is formed at a reference pressure the engine holds fixed.", "Because the mole fractions are normalised to one bar before the division."]'::jsonb, 1, 'A partial pressure is the total pressure multiplied by a mole fraction, so dividing one by the other leaves the ratio of the two mole fractions at any pressure whatsoever. Two mole percentages out of a gas analysis are enough to form it.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 2, 'The digest forms the H2S to CO2 ratio two ways at five pressures and prints the difference. What is the difference column?', '["Zero below the fugacity cap and non-zero above it.", "Small and falling as the pressure rises towards the cap.", "Zero at the shipped pressure and non-zero at every other.", "Zero at every pressure."]'::jsonb, 3, 'That is the whole claim. A ratio that moved with pressure would have been built from the wrong quantity, and the two routes agreeing at five pressures is what says it was not.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 3, 'What two mistakes does reaching the ratio through MOLE FRACTIONS catch?', '["An H2S partial pressure built without its mole fraction, and one handed a CO2 fugacity instead.", "A mole fraction typed as a percentage, and a pressure typed in psig.", "A total pressure above the cap, and a temperature below absolute zero.", "A CO2 fraction of zero, and an H2S fraction that is not a number."]'::jsonb, 0, 'Neither could ever be caught by writing the engine''s own ratio out a second time, because a copy of an expression agrees with the expression whatever either of them is doing. Two routes that share a step cannot test the step they share.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 4, 'In how many words does the regime door answer, and what are they?', '["Three: carbonate, sulphide and unknown, the mixed case being a flag on the rate.", "Two: whether the CO2 rate model applies and whether the rate is an upper bound.", "Four: carbonate, mixed, sulphide and unknown.", "Five, the fourth being a severity region."]'::jsonb, 2, 'There is no severity region anywhere in this engine. That claim was withdrawn, and the door reports a regime word and whether its own rate model still applies.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 5, 'The two ratios that separate those regimes were measured by bisecting the regime word. What is their status?', '["Both are published transition ratios that the engine cites in its own module docstring.", "Neither is sourced anywhere in this repository, both being held for literature.", "One of the two is published and the other was fitted to the vendored golden cases.", "Both are exported constants, so their sourcing travels with the export."]'::jsonb, 1, 'Exporting a constant says what the module declares and measuring one says what it actually uses. Neither says where the number came from, and a case near a boundary is near a line of unknown position.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 6, 'What does the engine do with the rate in the MIXED regime?', '["It issues the rate and flags it as an upper bound.", "It withholds the rate and keeps the band label and the remaining life.", "It refuses the whole screening, because two films are competing.", "It issues the rate with no flag at all."]'::jsonb, 0, 'Its own note is that with mixed sulphide and carbonate films the CO2 rate is an upper bound and the real rate depends on which film persists. A mixed film is a reason to read the number as a ceiling.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 7, 'Above the higher boundary the engine says a CO2-only rate model no longer describes the surface. What does it then report?', '["A refusal, because no rate at all can be issued once the model has stopped describing the surface.", "The rate, the band label and the remaining life, all three marked as ceilings.", "The rate and the remaining life, with only the band label withheld.", "The rate as a stated upper bound, with the band label and the remaining life withheld."]'::jsonb, 3, 'Two easier routes were available and the engine takes neither. Refusing the rate outright throws away a usable ceiling, and carrying on regardless is what a bare correlation does. This engine issues the number and tells you what kind of number it now is.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 8, 'On the studio''s shipped default case, what is the H2S to CO2 ratio and which regime does it reach?', '["0.333333333333, in the sulphide regime.", "0.140495867769, in the sulphide regime.", "0.033333333333, in the mixed regime.", "0.040000000000, in the mixed regime."]'::jsonb, 2, 'That ratio is formed from an H2S mole fraction of 0.001000 and a CO2 mole fraction of 0.030000, and it would be the same number at any total pressure.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 9, 'Raise the H2S on the studio''s shipped case from 0.1 to 1 mol percent. Why is the rate unchanged?', '["The regime change removes the corrosion inhibitor credit and the two effects cancel.", "H2S is not in the CO2 rate correlation, so it cannot move the rate.", "The engine holds the rate at its previous value once the regime word changes.", "The rate is recomputed and rounds to the same figure at six decimals."]'::jsonb, 1, 'The ratio becomes 0.333333333333 and the regime becomes sulphide. That the rate does not move is the lesson in one line, because H2S reaches the regime word and the threshold comparison and reaches the correlation nowhere at all.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 10, 'On the shipped case, what DOES change on the screen when the H2S goes from 0.1 to 1 mol percent?', '["Both of the fields a reader summarises by are held back, and the rate becomes a ceiling.", "The rate falls, and the band label and the remaining life follow it down.", "The wall shear rises, and the corrosion inhibitor credit is removed.", "Nothing changes, since the H2S reaches none of the reported fields."]'::jsonb, 0, 'Nothing failed open there. The arithmetic ran and its two summarising fields were held back, which is a withholding rather than a refusal.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 11, 'A case arrives with a CO2 partial pressure of zero. What does the regime door return?', '["The carbonate regime, since no CO2 means no competing sulphide film.", "The sulphide regime, since the ratio is unbounded above.", "The unknown regime, with a note saying which film governs is not known there.", "A refusal, because a ratio cannot be formed from a zero."]'::jsonb, 2, 'With no CO2 partial pressure there is no ratio to form. Both unknown branches carry a note, so a panel printing the note unconditionally always has a sentence to print.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 12, 'The sour service door compares one partial pressure against one threshold. What else does it do?', '["It classifies a severity region from the partial pressure and the pH.", "It recommends a material, a hardness limit and a weldment qualification for the line.", "It returns a sulphide stress cracking criterion alongside the comparison.", "It reports the comparison in two units and counts how far above in powers of ten."]'::jsonb, 3, 'There is no severity region and no material guidance. The engine reports both as not provided in fields of their own, so a caller cannot read the gap as a value somebody forgot to set.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 13, 'How far above the screening threshold does the shipped case sit?', '["0.455932 decades, which is the swept row an order of magnitude lower.", "1.163506 decades.", "1.455932 decades, which is the swept row an order of magnitude higher.", "0.000000 decades, the case sitting exactly on the threshold."]'::jsonb, 1, 'The decade count is the useful half of that door. A verdict of above the threshold is true of a stream a hair over the line and of one three orders of magnitude over it, and the count separates them without inventing a severity scale.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 14, 'At an H2S partial pressure of exactly zero, what does the engine report for the decade count?', '["An absence rather than a figure, because the logarithm of zero is not a screening result.", "Minus infinity, which the studio then renders as a dash.", "Zero, which is the count the threshold itself carries.", "The count the smallest swept partial pressure produces."]'::jsonb, 0, 'The sour flag is false on that case. Reporting an absence where the arithmetic has no answer is the same habit the oil-wet inhibition figure follows.'),
  ('corrosion', 'intermediate', 'module', 'm06-which-film-governs', 15, 'Why does this door print its threshold in both bar and psia?', '["So the reader can choose whichever unit the governing standard is written in.", "So the engine can compare the stream against whichever is the more limiting.", "So nobody has to convert, and so no second rounded copy of the number can drift from the first.", "So the studio is able to show the held value in the one unit and the sourced value in the other one."]'::jsonb, 2, 'A threshold quoted in one unit and compared in another is where conversion mistakes live. The engine derives the psia figure from the bar figure rather than carrying a separate rounded literal, and it declares in a field of its own that the VALUE is held.'),
  ('corrosion', 'intermediate', 'final', null, 1, 'Which single input on this screen is chosen from a list rather than measured, and takes the rate from 1.676428 mm/yr to zero with nothing else touched?', '["The wetting regime, which is chosen from a list of three.", "The in-situ pH, which moves the rate by a decade every two units.", "The velocity, which reaches the rate twice.", "The corrosion inhibitor availability."]'::jsonb, 0, 'Almost every other input is a measured quantity with a unit, and this one is a word that can zero the rate on its own.'),
  ('corrosion', 'intermediate', 'final', null, 2, 'Two of the three regimes ignore the water cut box entirely. What wetting factor does each of them use?', '["0.370000 water wet and 0.000000 oil wet.", "1.000000 water wet and 1.000000 oil wet.", "1.000000 water wet and 0.000000 oil wet.", "Whatever the box says, the regime word only labelling the row."]'::jsonb, 2, 'The box sits on the screen all the time and is read in one branch only. In the other two the factor is pinned at the top and at the bottom of its range.'),
  ('corrosion', 'intermediate', 'final', null, 3, 'A user types waterwette into the regime box. What comes back?', '["The water-wet branch, reached by the matcher''s fuzzy spelling rules.", "A refusal quoting the string and naming the three regimes the engine accepts.", "The intermittent branch, which is the middle of the three.", "A screening with the regime row marked as assumed."]'::jsonb, 1, 'Five spellings of oil wet resolve because they are unambiguous. A string the matcher cannot resolve refuses, because an unrecognised regime falling through would choose an input that can zero the rate from a typing mistake.'),
  ('corrosion', 'intermediate', 'final', null, 4, 'Which of these is not one of the three wetting regimes this engine accepts?', '["oilWet.", "waterWet.", "intermittent.", "gasWet."]'::jsonb, 3, 'The list is closed at three and there is no gas-wet, stratified or annular option. No door in this module works out a flow pattern, so the three entries are an interpretation the engineer supplies.'),
  ('corrosion', 'intermediate', 'final', null, 5, 'On an oil-wet case one reported field becomes null rather than zero. Which?', '["The wetting factor, which the regime sets.", "The effective corrosion inhibition.", "The wall shear, which no longer has a film to act on.", "The water cut."]'::jsonb, 1, 'With the rate zero by assumption, a percentage describing how much metal loss was removed has no subject. Reporting an absence is how the engine avoids making a claim about the chemical it was never in a position to make.'),
  ('corrosion', 'intermediate', 'final', null, 6, 'The regime is intermittent and the water cut box reads 0.000000. What comes back?', '["A wetting factor of 0.000000, which lands on the oil-wet answer from the other end.", "A refusal, because a water cut of zero is not a water cut at all.", "A wetting factor of 1.000000, supplied by the default parameter.", "A wetting factor of 0.370000, which is the shipped intermittent figure."]'::jsonb, 0, 'Both ends of the intermittent range coincide with one of the other two branches, and that is what makes it an interpolation rather than a third mechanism of its own.'),
  ('corrosion', 'intermediate', 'final', null, 7, 'Nought to one on every fraction is one of the range guards this module enforces. Which of these is another?', '["A velocity below an erosional limit for the line.", "A wall shear below the film-stripping threshold.", "Nought to fourteen on the in-situ pH.", "A rate below the top band edge the category table carries."]'::jsonb, 2, 'Nought to one on every fraction, nought to fourteen on pH, a temperature above absolute zero, and the partial-pressure sum against the total are all enforced on what a caller types. Every published validity band of every correlation is held rather than enforced.'),
  ('corrosion', 'intermediate', 'final', null, 8, 'Which row of the corrosion inhibitor table carries an effective protection of 90.250000 percent?', '["An efficiency of 95.000000 at an availability of 90.000000 percent.", "An efficiency of 95.000000 at an availability of 95.000000 percent.", "An efficiency of 90.000000 at an availability of 95.000000 percent.", "An efficiency of 95.000000 at an availability of 98.000000 percent."]'::jsonb, 1, 'Its shortfall is 4.750000 percentage points and its metal loss is 1.950000 times the datasheet number. Two inputs reach that figure and the engine asks for them one at a time.'),
  ('corrosion', 'intermediate', 'final', null, 9, 'Two percentage points of availability are lost, from 100.000000 to 98.000000, at an efficiency of 95.000000 percent. What is the metal loss then?', '["1.000000 times it.", "1.950000 times it, which is what a lower availability row carries.", "1.900000 times it, which is the shortfall in percentage points.", "1.380000 times the datasheet number."]'::jsonb, 3, 'The effective protection on that row is 93.100000 percent, a shortfall of 1.900000 percentage points, which reads as almost nothing. A reader who summarises by the protection column and one who summarises by the loss column are looking at the same row.'),
  ('corrosion', 'intermediate', 'final', null, 10, 'At 95.000000 percent efficiency and 70.000000 percent availability, what is the shortfall?', '["25.000000 percentage points, the drop in the availability.", "6.700000 percentage points, which is the metal loss ratio there.", "28.500000 percentage points short of the datasheet figure.", "19.000000 percentage points, which the row above it carries."]'::jsonb, 2, 'The effective protection there is 66.500000 percent and the metal loss is 6.700000 times the datasheet number. The chemical is the same 95 percent product on every row of that table.'),
  ('corrosion', 'intermediate', 'final', null, 11, 'On one row of the corrosion inhibitor table the effective protection and the shortfall are the same number. Which availability?', '["25.000000 percent, where both read 23.750000.", "50.000000 percent, where both read 47.500000.", "95.000000 percent, where both read 90.250000.", "100.000000 percent, where both read 95.000000."]'::jsonb, 1, 'Half the datasheet efficiency is delivered and half of it is lost, so the two columns meet. The metal loss on that row is 10.500000 times the datasheet number.'),
  ('corrosion', 'intermediate', 'final', null, 12, 'The availability box reads 130.000000 percent beside an efficiency of 90.000000. What protection is reported?', '["90.000000 percent.", "130.000000 percent, the availability being taken as typed.", "100.000000 percent, which is where the availability was clamped to.", "0.000000 percent, the whole case being rejected as impossible."]'::jsonb, 0, 'The engine moved the availability to its ceiling and recorded that move on the screening in a field of its own. That field is empty on the studio''s shipped case, where nothing was moved.'),
  ('corrosion', 'intermediate', 'final', null, 13, 'The warning on the studio''s shipped screen names a metal loss. What figure does it give?', '["4.80 times it, which is the figure at 80 percent availability.", "1.000000 times it.", "2.900000 times it.", "1.45 times the metal loss of the datasheet number."]'::jsonb, 3, 'The shipped programme is a 90 percent corrosion inhibitor at 95 percent availability, giving 85.5 percent effective protection. Those are the engine''s own words and the shortfall behind them is 4.500000 percentage points.'),
  ('corrosion', 'intermediate', 'final', null, 14, 'An efficiency of 120.000000 percent is typed. What does the engine report about it?', '["That it was rejected.", "That the efficiency was clamped from 120 to 100 percent.", "That the efficiency was accepted as typed, the arithmetic being valid.", "That the availability was clamped instead, to keep the product below one."]'::jsonb, 1, 'A percentage slightly outside its range is almost always a typing slip on a quantity whose intent is obvious, and the nearest valid value carries that intent. The declaration is what stops the convenience becoming a silent assumption.'),
  ('corrosion', 'intermediate', 'final', null, 15, 'Only one of the six screened streams falls outside the turbulent branch. Name it.', '["Tunu, at a Reynolds number of 1063231.0691.", "Opukushi, at a Reynolds number of 193290.8250.", "Angiama, at a Reynolds number of 3.3754.", "Etelebou, at a Reynolds number of 313781.4400."]'::jsonb, 2, 'Every other stream in that table sits in the hundreds of thousands or above. This one is small, slow and viscous, so it lands on a branch of its own.'),
  ('corrosion', 'intermediate', 'final', null, 16, 'The digest''s swept branch table carries seven rows. How many of them are flagged as near the switch?', '["Four.", "Seven, every row on the table being inside the flagged band.", "One, which is the row sitting exactly on the switch itself.", "Three."]'::jsonb, 0, 'The flag is set at 3600.0000, 3960.0000, 4000.0000 and 4040.0000, and clear at 2000.0000, 4400.0000 and 8000.0000.'),
  ('corrosion', 'intermediate', 'final', null, 17, 'On the two swept rows either side of the branch change, what pair of friction factors comes back?', '["It goes from 0.003660 to 0.002867, which is the spread across the streams.", "It stays at 0.046000000000, which is the Blasius coefficient itself.", "It goes from 4.740191 to 0.008591, which is a fall of three orders.", "It goes from 0.004000 to 0.008739."]'::jsonb, 3, 'Those two rows sit at 4000.0000 and 4040.0000, and the wall shear across them goes from 0.003200 Pa to 0.007132 Pa. Across the switch itself, over two ten-thousandths of the Reynolds number, the jump is 2.189815.'),
  ('corrosion', 'intermediate', 'final', null, 18, 'The velocity sweep runs at 8.000000 m/s. What wall shear does this module return there?', '["100.000000 Pa, which is where the film-stripping verdict turns.", "97.225957 Pa.", "201.718855 Pa, which is the row at 12.000000 m/s.", "27.920824 Pa, which is the row at 4.000000 m/s."]'::jsonb, 1, 'That row is below the stripping threshold and the corrosion inhibitor credit is still taken on it. At 12.000000 m/s the shear is 201.718855 Pa and the credit is removed.'),
  ('corrosion', 'intermediate', 'final', null, 19, 'The engine''s own note near the friction branch switch ends with an instruction. What is it?', '["To lower the velocity until the Reynolds number leaves the switch.", "To take the laminar value.", "To read the shear as a bracket rather than as a single value.", "To average the two branch values."]'::jsonb, 2, 'Near the switch the shear is a range with two candidates in it. Away from the switch it is a single number, which is what the flag is telling you.'),
  ('corrosion', 'intermediate', 'final', null, 20, 'The velocity box is blank and the shear door is called. What is the engine''s own message?', '["Wall shear stress needs a positive velocity.", "A positive velocity is required, an absent velocity not being unlimited capacity.", "Screening incomplete, because the film survival check could not be run.", "The velocity must be finite."]'::jsonb, 0, 'Four inputs reach that door and each of the four refusals names its own box. The longer sentences belong to other doors on the same engine, and quoting the wrong one attributes a message to a call that never produced it.'),
  ('corrosion', 'intermediate', 'final', null, 21, 'One digest stream has a friction factor of 4.740191 and another has 0.002867. Why are they so far apart?', '["One is a Fanning factor and the other is a Darcy factor.", "One was measured on the engine and the other read from its export.", "One is this module''s factor and the other is the line sizing course''s.", "They come from two different expressions, one on each branch."]'::jsonb, 3, 'Neither branch is wrong on its own ground, and nothing in either expression requires the two to agree at any particular Reynolds number. Both expressions and the switch between them are held for literature.'),
  ('corrosion', 'intermediate', 'final', null, 22, 'Of the six streams the digest screens, how many have their corrosion inhibitor film stripped?', '["None, every one of the six sitting below the threshold.", "One.", "Three, being the three with the highest wall shear figures.", "Six, the credit being removed on every stream in the table."]'::jsonb, 1, 'On the five others the rate column and the credited rate column carry the same figure and the two life columns carry the same figure, so the ratio between them is 1.000000.'),
  ('corrosion', 'intermediate', 'final', null, 23, 'On the one stripped stream, what are the two remaining lives the engine reports?', '["1.655305 yr against 7.681561 yr.", "4.207953 yr, against 0.242737 yr once the credit has been kept.", "0.161915 yr, against 0.760876 yr with the credit kept.", "36.112878 yr against 192.123424 yr."]'::jsonb, 2, 'That is the cost of the shear verdict stated in years on the same row as the verdict itself. The two lives carry the same information as the two rates, because the allowance is common to both.'),
  ('corrosion', 'intermediate', 'final', null, 24, 'The engine''s warning when the credit is removed says two useful things. What are they?', '["It names the datasheet figure that stopped applying, and says the rate above is now the uninhibited one.", "It names the stripping threshold, and gives the velocity that would restore the film.", "It names the band label, and gives the allowance a reinstatement would need.", "It names the wetting regime, and gives the water cut the regime was read at."]'::jsonb, 0, 'The reader can see which number stopped applying and what the headline figure now is, rather than working the second out from the first.'),
  ('corrosion', 'intermediate', 'final', null, 25, 'Why does a stripped rate divided by its credited rate carry no held constant at all?', '["Because the constants cancel between the two branches of the friction factor.", "Because the two run the same chain on the same inputs, so everything but one factor divides out.", "Because the quotient is formed from mole fractions, which need no pressure.", "Because the engine forms the quotient from the typed percentages directly."]'::jsonb, 1, 'They differ in exactly one factor, which is the corrosion inhibitor credit. Every coefficient and every correction appears identically on both sides.'),
  ('corrosion', 'intermediate', 'final', null, 26, 'On a case where the corrosion inhibitor credit was taken in full, what does the credited rate column show?', '["A blank.", "The uninhibited rate, which is what the credit was taken off.", "The rate the datasheet would give at one hundred percent availability.", "The same figure the rate column shows."]'::jsonb, 3, 'The engine reports both on every case whether or not the credit was actually taken. Printing a figure twice looks redundant until you meet the case where they differ.'),
  ('corrosion', 'intermediate', 'final', null, 27, 'Why is a blank density here not simply a missing row on the summary?', '["Because the density is an argument of the correlation the rate comes from.", "Because a remaining life cannot be divided without a density for the stream.", "Because the rate depends on the film verdict, so the module would not know which of two rates to issue.", "Because the wetting regime is resolved from the density of the phase."]'::jsonb, 2, 'The screening computes the wall shear first for exactly this reason. Issuing a rate while the credit question is open would be choosing between two candidates on the reader''s behalf.'),
  ('corrosion', 'intermediate', 'final', null, 28, 'On the studio''s shipped default case, what does the film verdict say and at what wall shear?', '["Not stripped, at a wall shear of 14.408065 Pa.", "Stripped, at a wall shear of 362.474888 Pa.", "Not stripped, at a wall shear of 369.638295 Pa.", "Stripped, at a wall shear of 100.000000 Pa."]'::jsonb, 0, 'Nothing was taken away on that screen, so the two rate columns carry one figure between them. The verdict moves only once the velocity is raised.'),
  ('corrosion', 'intermediate', 'final', null, 29, 'Which two figures does the shipped screening set against each other to reach its design life verdict?', '["The 3.175000 mm allowance, against the 15.090473 mm demanded.", "The 4.207953 yr the allowance reaches, against the 20.000000 yr asked for.", "The 11.915473 mm gap, against the 3.175000 mm allowance.", "The remaining allowance, against a minimum thickness held internally."]'::jsonb, 1, 'The engine prints the life it actually reaches beside the life it was given, and it says which of the two governs. There is no minimum thickness anywhere in this module to compare anything against.'),
  ('corrosion', 'intermediate', 'final', null, 30, 'Put a consumed depth into the box on a case that had none. Which fields move?', '["The required allowance alone.", "The rate and the band label, both of which are taken off the wall that is left.", "The wall shear and the film verdict, which are taken on the reduced bore.", "The remaining allowance, the remaining life and the shortfall."]'::jsonb, 3, 'The allowance a design life demands is the rate multiplied by that design life. It is the allowance a new line would need, so it takes no account of what has already been consumed.'),
  ('corrosion', 'intermediate', 'final', null, 31, 'Two of the digest''s streams report remaining lives of 36.112878 yr and 192.123424 yr. What does a life of that size tell you?', '["How long the typed allowance lasts at the computed rate, and nothing more.", "When the line should next be inspected, counted in years from today''s date onwards.", "How long before the wall reaches its retirement thickness.", "Whether the line remains fit for service over that period."]'::jsonb, 0, 'An inspection interval, a minimum thickness, a retirement thickness and a fitness-for-service assessment are all listed by the engine as not provided. A reader who treats the years as an inspection date has read a division as a programme.'),
  ('corrosion', 'intermediate', 'final', null, 32, 'The wall this studio is consuming an allowance off is which wall?', '["The pressure-containing wall the line sizing studio sized.", "The shell course the storage tank studio sized.", "One the module knows nothing about, since it holds no thickness of its own.", "The wall the vendored golden''s own cases were built against."]'::jsonb, 2, 'Nothing carries a thickness from one app to another and no minimum thickness exists anywhere in this module. If somebody sizes a line in one studio and screens it in this one, the two allowances agree only because a person made them agree.'),
  ('corrosion', 'intermediate', 'final', null, 33, 'How many entries does each of the engine''s two absence lists carry?', '["Eleven not provided and eight held for literature.", "Eight not provided and eleven held for literature.", "Eight in each of the two lists the engine exports.", "Eleven in each of the two lists the engine exports."]'::jsonb, 1, 'The screening returns both so a caller shows the absences rather than meeting them one at a time. The studio prints the second list behind a disclosure.'),
  ('corrosion', 'intermediate', 'final', null, 34, 'How should the name of this studio be expanded honestly?', '["A fitness-for-service assessment with a corrosion rate feeding it.", "An inspection planning tool built on a sour-service severity region.", "A wall thickness calculator that sizes a line against a design life.", "A CO2 corrosion rate screen with a remaining-life division on the end of it."]'::jsonb, 3, 'That is a useful tool and a narrower one than the title suggests. The word integrity here means one arithmetic, and a reader who takes the remaining life for an inspection plan has crossed into what a standard would have to supply.'),
  ('corrosion', 'intermediate', 'final', null, 35, 'What does this module hold that would let it say how much wall sits under the allowance?', '["Nothing at all, because it carries no minimum thickness of any kind.", "A thin-wall relation with a design factor typed in beside it.", "A retirement thickness, which the reader supplies on the form.", "The wall the line sizing studio computed for the same pipe."]'::jsonb, 0, 'A corrosion allowance divided by a rate is the whole arithmetic here. What the allowance is being taken off is a question this studio cannot reach, and the course names the owner and stops.'),
  ('corrosion', 'intermediate', 'final', null, 36, 'One digest stream sits at an H2S to CO2 ratio of 0.140495867769. What does the engine report for it?', '["The mixed regime, with the rate flagged as an upper bound.", "The carbonate regime, the CO2 rate model applying in full.", "The sulphide regime, with the band label and the life both null.", "The unknown regime, with a note saying that no ratio at all could be formed."]'::jsonb, 2, 'Its withheld block names the rate as an upper bound. The engine could have refused the rate entirely or graded it as if nothing had changed, and it does neither.'),
  ('corrosion', 'intermediate', 'final', null, 37, 'A stream carries a CO2 mole fraction of 0.020000 and an H2S mole fraction of 0.000010. Which regime?', '["Mixed, at a ratio of 0.000500000000.", "Carbonate, at a ratio of 0.000500000000.", "Sulphide, at a ratio of 0.050000000000.", "Unknown, the H2S fraction being too small to form a ratio."]'::jsonb, 1, 'In that regime the CO2 rate model applies and the rate is issued plainly, with no upper-bound flag on it. The ratio is the same at any total pressure whatever.'),
  ('corrosion', 'intermediate', 'final', null, 38, 'A stream at a CO2 mole fraction of 0.020000 has its H2S mole fraction raised from 0.000010 to 0.000800. What happens?', '["The ratio becomes 0.040000000000 and the regime stays carbonate.", "The ratio becomes 0.040000000000 and the regime becomes mixed.", "The ratio falls and the regime becomes sulphide.", "The ratio is unchanged."]'::jsonb, 1, 'In the mixed regime the model still applies and the rate is issued with a flag saying it is a ceiling. Three regimes are three positions on the same question about one rate.'),
  ('corrosion', 'intermediate', 'final', null, 39, 'The sour door is handed a blank H2S partial pressure. What comes back?', '["The H2S partial pressure must be non-negative.", "A comparison taken at zero.", "The unknown regime, with a note about the missing ratio.", "A finite H2S partial pressure is required."]'::jsonb, 3, 'That door owns two refusals and each names its input. A negative partial pressure gets the other of the two, and a partial pressure of exactly zero is answered rather than refused.'),
  ('corrosion', 'intermediate', 'final', null, 40, 'An H2S partial pressure of zero reaches the sour door. Is that a refusal?', '["No. The comparison is answered, and the decade count is reported as an absence.", "Yes, because a partial pressure of zero fails the finiteness check.", "Yes, because the logarithm the door forms is undefined there.", "No, and the decade count comes back as minus infinity."]'::jsonb, 0, 'A typed zero is a positive assertion and a blank box is a question the engine cannot answer, and this module treats the two differently throughout.'),
  ('corrosion', 'intermediate', 'final', null, 41, 'The threshold this door compares against is printed in psia as 0.050763208303. How was that figure reached?', '["It was read from the published standard the threshold comes from.", "It was rounded to twelve figures from a value of exactly 0.05 psia.", "It was derived from the bar value rather than rounded or typed separately.", "It was fitted so that the golden''s psia rows would agree with the engine."]'::jsonb, 2, 'Carrying a second rounded literal is how two copies of one threshold drift apart. The engine prints both units from one number, and it declares in a field of its own that the VALUE is held for literature.'),
  ('corrosion', 'intermediate', 'final', null, 42, 'Where does the H2S to CO2 ratio reach, once it has produced its regime word?', '["It enters no calculation, and through the regime word it decides whether the band label and the life are issued.", "The rate, which it multiplies by a sulphide correction factor.", "The wall shear, through the density of the sour phase.", "The allowance division, which it shortens in the sulphide regime."]'::jsonb, 0, 'Its job is to say whether a CO2 rate model is still the right model for the surface. In the sulphide regime that withholds the band label and the life and keeps the rate as a stated upper bound, and the rate itself does not move.');
